async function fetchDocsForTargets(
    lead: any,
    targets: CedenteEsteiraTarget[],
    existingDocs: Dashboard2DocsCedenteRow[],
): Promise<{ docs: Dashboard2DocsCedenteRow[]; exigencias: Dashboard2EsteiraExigenciaCondicional[] }> {
    const byEsteira = new Map<number, CedenteEsteiraTarget[]>();
    for (const target of targets) {
        const bucket = byEsteira.get(target.esteiraId) || [];
        bucket.push(target);
        byEsteira.set(target.esteiraId, bucket);
    }

    const docsByCedente: Dashboard2DocsCedenteRow[] = [];
    const exigenciasById = new Map<number, Dashboard2EsteiraExigenciaCondicional>();

    for (const [esteiraId, group] of Array.from(byEsteira.entries())) {
        const [rows, exigencias] = await Promise.all([
            getDocsFromEsteira(esteiraId) as Promise<Dashboard2EsteiraDocRow[]>,
            getEsteiraExigenciasCondicionais(esteiraId),
        ]);
        for (const exigencia of exigencias) {
            if (exigencia?.ativa) exigenciasById.set(exigencia.id, exigencia);
        }
        for (const target of group) {
            const existingForCedente = existingDocs.filter(
                (doc) => String(doc.relation_id || '') === target.relationId,
            );
            const merged = dashboard2MergeEsteiraApiDocsIntoDocsCedente(rows, target.isPj, existingForCedente);
            for (const doc of merged) {
                docsByCedente.push({
                    ...doc,
                    relation_id: target.representedPjRelationId && shouldAttachDocToRepresentedPj(doc)
                        ? target.representedPjRelationId
                        : target.relationId,
                });
            }
        }
    }

    const managedRelationIds = new Set(targets.map((target) => target.relationId));
    const unmanagedDocs = existingDocs.filter((doc) => {
        if (!doc.relation_id) return true;
        return !managedRelationIds.has(String(doc.relation_id));
    });

    return {
        docs: dashboard2RemapDocsCedenteRelationIds([...unmanagedDocs, ...docsByCedente], lead),
        exigencias: Array.from(exigenciasById.values()),
    };
}

async function fetchDocsFallbackCrmEsteira(
    lead: any,
): Promise<{ docs: Dashboard2DocsCedenteRow[]; exigencias: Dashboard2EsteiraExigenciaCondicional[] }> {
    const eid = Number(lead?.crm_kyc_esteira_id);
    if (!Number.isFinite(eid) || eid <= 0) {
        return {
            docs: Array.isArray(lead.docsCedente) ? lead.docsCedente : [],
            exigencias: Array.isArray(lead._exigenciasCondicionais) ? lead._exigenciasCondicionais : [],
        };
    }

    const cedentes = dashboard2GetCanonicalCedentes(lead);
    const defaultRelationId = cedentes[0]?.relation_id ? String(cedentes[0].relation_id) : 'principal';
    const existing = Array.isArray(lead.docsCedente) ? lead.docsCedente as Dashboard2DocsCedenteRow[] : [];
    const [rows, exigencias] = await Promise.all([
        getDocsFromEsteira(eid) as Promise<Dashboard2EsteiraDocRow[]>,
        getEsteiraExigenciasCondicionais(eid),
    ]);

    return {
        docs: dashboard2RemapDocsCedenteRelationIds(
            dashboard2MergeEsteiraApiDocsIntoDocsCedente(rows, resolveLeadIsPj(lead), existing).map((doc) => ({
                ...doc,
                relation_id: doc.relation_id ?? defaultRelationId,
            })),

